/** Faultline / Swarm, rules v3. 127 hexes. */
export const VERSION='faultline-swarm/3',RADIUS=6;
export const D=[[1,0],[0,1],[-1,1],[-1,0],[0,-1],[1,-1]],B=[[1,1],[-1,2],[-2,1],[-1,-1],[1,-2],[2,-1]];
export const N=D.flatMap((d,i)=>{const e=D[(i+1)%6];return [[2*d[0]+e[0],2*d[1]+e[1]],[d[0]+2*e[0],d[1]+2*e[1]]];});
export const CELLS=[];for(let r=-6;r<=6;r++)for(let q=-6;q<=6;q++)if(Math.abs(q+r)<=6)CELLS.push({q,r,id:`${q},${r}`,label:String.fromCharCode(71+q)+(r+7)});
export const CELL=Object.fromEntries(CELLS.map(c=>[c.id,c]));
export const ROLES=Object.fromEntries([['p','Pawn',100,2],['n','Knight',320,3],['b','Bishop',340,3],['r','Rook',510,4],['q','Queen',930,6],['k','King',20000,0],['w','Warden',600,5],['a','Archbishop',720,6],['c','Chancellor',850,7],['e','Bee',240,2],['h','Hive',420,4],['v','Hornet',400,4],['m','Mimic',400,4],['t','Anchor',260,3],['u','Courier',230,3],['s','Bastion',420,4],['l','Lancer',430,4]].map(([t,name,value,cost])=>[t,{name,value,cost,short:t==='e'?'Be':t.toUpperCase()}]));
export const RECIPES={'p+p':['n'],'n+p':['w'],'b+n':['a','m'],'n+r':['c'],'b+r':['q'],'e+e':['h','v'],'p+r':['s','l']};
export const other=c=>c==='w'?'b':'w',label=id=>CELL[id]?.label||id,edge=(a,b)=>[a,b].sort().join('|');
export const distance=(a,b='0,0')=>{const u=CELL[a],v=CELL[b];return Math.max(Math.abs(u.q-v.q),Math.abs(u.r-v.r),Math.abs(u.q+u.r-v.q-v.r));};
const step=(id,d,k=1)=>{const c=CELL[id];return `${c.q+d[0]*k},${c.r+d[1]*k}`;},near=id=>D.map(d=>step(id,d)).filter(id=>CELL[id]);
const unit=(t,c,parts=[t])=>({t,c,parts});
export function initial(){const s={version:VERSION,board:{},turn:'w',ply:0,flux:{w:3,b:3},reserve:{w:['p','n','e'],b:['p','n','e']},walls:[],gates:{w:[],b:[]},guards:{w:null,b:null},royal:{w:true,b:true},swarm:null,core:null,passes:0,quiet:0,winner:null,reason:null};const set=(q,r,t)=>{s.board[`${q},${r}`]=unit(t,'w');s.board[`${-q},${-r}`]=unit(t,'b');};['r','n','k','n','r'].forEach((t,i)=>set(i-5,6,t));['b','p','q','p','b','p'].forEach((t,i)=>set(i-5,5,t));for(let q=-4;q<=0;q++)set(q,4,'p');['e','e','m','t','u'].forEach((t,i)=>set(i-4,3,t));return s;}
function blocked(s,from,to){const has=(a,b)=>s.walls.some(w=>w.key===edge(a,b));if(distance(from,to)===1)return has(from,to);return near(from).filter(j=>distance(j,to)===1).some(j=>has(from,j)||has(j,to));}
export function anchored(s,id){const p=s.board[id];return !!p&&near(id).some(j=>s.board[j]?.c!==p.c&&s.board[j]?.t==='t');}
function gates(s,id){return Object.values(s.gates).filter(g=>g.length===2&&g.includes(id)).map(g=>g[0]===id?g[1]:g[0]);}
export function targets(s,id,attack=false,asType=null){const p=s.board[id];if(!p)return [];const t=asType||p.t,out=new Set(),bound=anchored(s,id),add=j=>{if(CELL[j]&&(attack||s.board[j]?.c!==p.c))out.add(j);};const ray=(dirs,limit=12)=>{for(const d of dirs){let prev=id;for(let n=1;n<=limit;n++){const j=step(id,d,n);if(!CELL[j]||blocked(s,prev,j))break;add(j);if(s.board[j])break;prev=j;}}};
if(t==='m'){const copies=new Set(near(id).map(j=>s.board[j]).filter(x=>x?.c===p.c&&['p','n','b','r'].includes(x.t)).map(x=>x.t));if(copies.size)for(const type of copies)for(const j of targets(s,id,attack,type))out.add(j);else if(!attack)for(const j of near(id))if(!s.board[j]&&!blocked(s,id,j))out.add(j);return [...out];}
if(t==='p'){const f=p.c==='w'?-1:1,j=step(id,[0,f]);if(!attack&&CELL[j]&&!s.board[j]&&!blocked(s,id,j))add(j);for(const d of [[f,0],[-f,f]]){const j=step(id,d);if(CELL[j]&&!blocked(s,id,j)&&(attack||(s.board[j]&&s.board[j].c!==p.c)))add(j);}}
if(['r','q','c'].includes(t))ray(D);if(['b','q','a'].includes(t))ray(B);if(['n','a','c','w'].includes(t)&&!bound)for(const d of N)add(step(id,d));if(['k','t'].includes(t))ray(D,1);if(['w','s'].includes(t))ray(D,2);if(t==='l')ray(p.c==='w'?[[0,-1],[-1,0],[1,-1]]:[[0,1],[1,0],[-1,1]],3);
if(['e','v'].includes(t)){for(const j of near(id))if(!blocked(s,id,j)&&(attack||!s.board[j]||s.board[j].c!==p.c))add(j);if(!attack&&!bound)for(const d of D)for(let n=2;n<=(t==='e'?2:3);n++){const j=step(id,d,n);if(CELL[j]&&!s.board[j])add(j);}}
if(t==='u'&&!attack){for(const d of D){let prev=id;for(let k=1;k<=(p.cargo?1:2);k++){const j=step(id,d,k);if(!CELL[j]||s.board[j]||blocked(s,prev,j))break;out.add(j);prev=j;}}}
if(t!=='h'&&!bound)for(const j of gates(s,id))if(t==='u'?!attack&&!s.board[j]:true)add(j);return [...out];}
export function threatened(s,c){const k=Object.keys(s.board).find(id=>s.board[id].c===c&&s.board[id].t==='k');return !!k&&Object.keys(s.board).some(id=>s.board[id].c!==c&&targets(s,id,true).includes(k));}
export const fuseTypes=(a,b)=>RECIPES[[a,b].sort().join('+')]||[],fuseType=(a,b)=>fuseTypes(a,b)[0];
const promotion=(p,to)=>p.t==='p'&&!CELL[step(to,[0,p.c==='w'?-1:1])];
export function actionId(a){return JSON.stringify(Object.fromEntries(Object.entries(a).filter(([k])=>k!=='id').sort(([a],[b])=>a.localeCompare(b))));}
export function actions(s,{construction=true}={}){if(s.winner)return [];const out=[],c=s.turn,f=s.flux[c],add=a=>{a.id=actionId(a);out.push(a);};if(s.swarm){for(const [from,p] of Object.entries(s.board))if(p.c===c&&p.t==='e'&&from!==s.swarm)for(const to of near(from))if(!s.board[to]&&!blocked(s,from,to))add({kind:'swarm',from,to});add({kind:'finish'});return out;}
for(const [from,p] of Object.entries(s.board)){if(p.c!==c)continue;for(const to of targets(s,from)){if(promotion(p,to))for(const promote of ['q','r','b','n'])add({kind:'move',from,to,promote});else add({kind:'move',from,to});}
if(f>=2&&p.t!=='k'&&!p.cargo&&!anchored(s,from))for(const to of near(from)){const mate=s.board[to];if(mate?.c===c&&!mate.cargo&&!anchored(s,to)&&!blocked(s,from,to))for(const result of fuseTypes(p.t,mate.t))add({kind:'fuse',from,to,result});}
if(p.t==='h'){const free=near(from).filter(j=>!s.board[j]);for(let i=0;i<free.length;i++)for(let j=i+1;j<free.length;j++)add({kind:'split',from,to:free[i],second:free[j]});}
if(p.t==='u')for(const to of near(from)){if(blocked(s,from,to))continue;if(p.cargo&&!s.board[to])add({kind:'unload',from,to});else if(!p.cargo&&s.board[to]?.c===c&&!['k','h','u'].includes(s.board[to].t))add({kind:'load',from,to});}
if(p.t==='k'&&s.royal[c])for(const to of near(from))if(s.board[to]?.c===c&&s.board[to].t==='p'&&s.board[to].parts.length===1&&!blocked(s,from,to))add({kind:'exchange',from,to});
if(!['h','u','m'].includes(p.t))for(const to of targets(s,from,true))if(s.board[to]?.c!==c)add({kind:'guard',from,to});}
for(const t of new Set(s.reserve[c]))if(f>=ROLES[t].cost)for(const cell of CELLS)if(!s.board[cell.id]&&((c==='w'?cell.r>=5:cell.r<=-5)||(t==='e'&&near(cell.id).some(j=>s.board[j]?.c===c&&s.board[j].t==='h'))))add({kind:'deploy',to:cell.id,piece:t});
if(s.board['0,0']?.c===c){add({kind:'harvest'});for(const [from,p] of Object.entries(s.board))if(p.c===c&&p.t!=='k')add({kind:'recall',from,to:from});for(const [from,p] of Object.entries(s.board))if(p.c===c&&p.parts.length===2&&!anchored(s,from))for(const result of fuseTypes(...p.parts))if(result!==p.t)add({kind:'reforge',from,to:from,result});}
if(construction){const mine=s.walls.filter(w=>w.owner===c);for(const w of mine)add({kind:'wall',key:w.key,remove:true});if(f>=1&&mine.length<2)for(const cell of CELLS)for(const d of D.slice(0,3)){const j=step(cell.id,d);if(CELL[j]&&!s.walls.some(w=>w.key===edge(cell.id,j)))add({kind:'wall',key:edge(cell.id,j)});}
if(f>=2)for(let slot=0;slot<Math.min(2,s.gates[c].length+1);slot++){const old=s.gates[c][slot];if(old&&s.board[old])continue;for(const cell of CELLS){if(cell.id==='0,0'||s.board[cell.id]||(c==='w'?cell.r<=0:cell.r>=0)||Object.values(s.gates).flat().includes(cell.id))continue;const second=s.gates[c][1-slot];if(second&&distance(second,cell.id)<=1)continue;add({kind:'gate',slot,to:cell.id});}}}
add({kind:'pass'});return out;}
function reserve(n,p){if(p.t==='k')return;n.reserve[p.c].push(...p.parts);if(p.cargo)reserve(n,p.cargo);}
function capture(n,id,by){const p=n.board[id];if(!p)return;if(p.t==='k'){n.winner=by;n.reason='King captured';}else reserve(n,p);delete n.board[id];n.flux[by]=Math.min(8,n.flux[by]+1);n.quiet=0;for(const c of ['w','b'])if(n.guards[c]?.from===id)n.guards[c]=null;}
function reaction(n,id){if(n.winner)return;const p=n.board[id];if(!p)return;const c=other(p.c),g=n.guards[c];if(!g||g.to!==id||n.board[g.from]?.c!==c)return;const protectedByBastion=p.t!=='k'&&near(id).some(j=>n.board[j]?.c===p.c&&n.board[j].t==='s');if(protectedByBastion||!targets(n,g.from,true).includes(id))return;const guard=n.board[g.from];capture(n,id,c);delete n.board[g.from];n.board[id]=guard;n.guards[c]=null;if(promotion(guard,id)){guard.t='q';guard.parts=['q'];}}
function finish(n,c){n.swarm=null;n.turn=other(c);n.guards[n.turn]=null;n.core=n.board['0,0']?.c||null;if(!n.winner&&n.passes>=4){n.winner='draw';n.reason='Four consecutive passes';}if(!n.winner&&n.quiet>=100){n.winner='draw';n.reason='100 quiet turns';}return n;}
export function apply(s,a){const n=structuredClone(s),c=s.turn,follow=!!s.swarm;if(!follow){n.ply++;n.quiet++;n.passes=a.kind==='pass'?s.passes+1:0;}const moved=n.board[a.from],wasEmpty=a.to&&!n.board[a.to];if(n.guards[c]?.from===a.from)n.guards[c]=null;
if(['move','swarm'].includes(a.kind)){delete n.board[a.from];if(n.board[a.to])capture(n,a.to,c);n.board[a.to]=moved;if(a.promote){moved.t=a.promote;moved.parts=[a.promote];}if(s.board[a.from]?.t==='p')n.quiet=0;reaction(n,a.to);}
if(a.kind==='fuse'){const p=n.board[a.from],v=n.board[a.to];delete n.board[a.from];n.board[a.to]=unit(a.result,c,[...p.parts,...v.parts]);n.flux[c]-=2;n.quiet=0;reaction(n,a.to);}
if(a.kind==='deploy'){n.reserve[c].splice(n.reserve[c].indexOf(a.piece),1);n.board[a.to]=unit(a.piece,c);n.flux[c]-=ROLES[a.piece].cost;n.quiet=0;reaction(n,a.to);}
if(a.kind==='split'){delete n.board[a.from];n.board[a.to]=unit('e',c);n.board[a.second]=unit('e',c);n.quiet=0;reaction(n,a.to);reaction(n,a.second);}
if(a.kind==='load'){n.board[a.from].cargo=n.board[a.to];delete n.board[a.to];n.quiet=0;}
if(a.kind==='unload'){n.board[a.to]=n.board[a.from].cargo;delete n.board[a.from].cargo;n.quiet=0;reaction(n,a.to);}
if(a.kind==='exchange'){[n.board[a.from],n.board[a.to]]=[n.board[a.to],n.board[a.from]];n.royal[c]=false;n.quiet=0;reaction(n,a.to);reaction(n,a.from);}
if(a.kind==='guard')n.guards[c]={from:a.from,to:a.to};
if(a.kind==='harvest')n.flux[c]=Math.min(8,n.flux[c]+3);
if(a.kind==='recall'){reserve(n,n.board[a.from]);delete n.board[a.from];n.quiet=0;}
if(a.kind==='reforge'){n.board[a.from].t=a.result;n.quiet=0;}
if(a.kind==='wall'){if(a.remove)n.walls=n.walls.filter(w=>w.key!==a.key);else{n.walls.push({key:a.key,owner:c});n.flux[c]--;}n.quiet=0;}
if(a.kind==='gate'){n.gates[c][a.slot]=a.to;n.flux[c]-=2;n.quiet=0;}
if(a.kind==='pass')n.flux[c]=Math.min(8,n.flux[c]+1);
n.core=n.board['0,0']?.c||null;
if(a.kind==='move'&&moved?.t==='e'&&wasEmpty&&!n.winner&&n.board[a.to]===moved&&Object.entries(n.board).some(([id,p])=>id!==a.to&&p.c===c&&p.t==='e'&&near(id).some(j=>!n.board[j]&&!blocked(n,id,j)))){n.swarm=a.to;return n;}
return finish(n,c);}
export function play(s,a){const id=typeof a==='string'?a:actionId(a),valid=actions(s).find(a=>a.id===id);if(!valid)throw new Error('Illegal or stale action');return apply(s,valid);}
export function describe(s,a){if(a.kind==='finish')return 'Finish swarm';if(a.kind==='pass')return 'Pass · +1 flux';if(a.kind==='harvest')return 'Nexus harvest · +3 flux';if(['fuse','reforge'].includes(a.kind))return `${a.kind==='fuse'?label(a.from)+' + ': 'Reforge '}${label(a.to)} → ${ROLES[a.result].name}`;if(a.kind==='deploy')return `${ROLES[a.piece].name} ↗ ${label(a.to)}`;if(a.kind==='wall')return `${a.remove?'Remove':'Build'} wall ${a.key.split('|').map(label).join(' / ')}`;if(a.kind==='gate')return `Gate ${a.slot+1} → ${label(a.to)}`;if(a.kind==='split')return `Split Hive → ${label(a.to)} + ${label(a.second)}`;if(['guard','load','unload','exchange','recall','swarm'].includes(a.kind))return `${a.kind[0].toUpperCase()+a.kind.slice(1)} ${label(a.from)} → ${label(a.to)}`;return `${ROLES[s.board[a.from].t].short} ${label(a.from)} ${s.board[a.to]?'×':'→'} ${label(a.to)}${a.promote?' = '+ROLES[a.promote].short:''}`;}
export function evaluate(s,c){if(s.winner)return s.winner==='draw'?0:s.winner===c?1e7:-1e7;let v=0;for(const [id,p] of Object.entries(s.board)){const sign=p.c===c?1:-1;v+=sign*(ROLES[p.t].value+(p.cargo?ROLES[p.cargo.t].value:0)+(p.t==='k'?distance(id)*9:(6-distance(id))*14));if(p.t==='p')v+=sign*(p.c==='w'?6-CELL[id].r:6+CELL[id].r)*9;}v+=(s.flux[c]-s.flux[other(c)])*15;v+=(s.board['0,0']?.c===c?90:s.board['0,0']?.c===other(c)?-90:0);if(threatened(s,c))v-=16000;if(threatened(s,other(c)))v+=400;return v;}
export function chooseAction(s,{seed=1,depth=2}={}){let rng=seed>>>0;const random=()=>{rng=(Math.imul(rng,1664525)+1013904223)>>>0;return rng/4294967296;};const c=s.turn,start=Date.now();let nodes=0;const all=actions(s),ranked=all.map(a=>{const n=apply(s,a);nodes++;return {a,n,score:evaluate(n,c)+(a.kind==='pass'?-22:0)+(a.kind==='wall'?-12:0)+(a.kind==='gate'?-12:0)+(a.kind==='guard'?-20:0)+random()*9};}).sort((a,b)=>b.score-a.score);
if(!ranked.length)return {action:null,nodes,ms:Date.now()-start};let best=ranked[0];if(depth>1&&best.n.winner!==c&&!s.swarm){let bestValue=-Infinity;for(const entry of ranked.slice(0,8)){let worst=Infinity;const replies=entry.n.turn===c?[]:actions(entry.n,{construction:false});if(!replies.length)worst=entry.score;if(entry.n.winner)worst=evaluate(entry.n,c);for(const reply of replies){nodes++;const value=evaluate(apply(entry.n,reply),c);worst=Math.min(worst,value);}const value=worst*.85+entry.score*.15;if(value>bestValue){bestValue=value;best=entry;}}}
return {action:best.a,nodes,ms:Date.now()-start,score:Math.round(best.score),candidates:all.length};}
